/* KAGAMI D-165 Jalur A B4: hitungan harian GDELT; PROTOCOL.md sha256 e6b46d952a4f79396a8a7c6370034b15584d0af635948d315564fb8a2a59e187; b_bq_daily_counts.sql sha256 6d7535d460d0ac33e49be2e917244503031e1d691e3f781730e2f580a5a3ef27 */ WITH base AS ( SELECT DATE(PARSE_TIMESTAMP('%Y%m%d%H%M%S', CAST(DATE AS STRING))) AS day_utc, SourceCommonName AS src, LOWER(CONCAT( IFNULL(REGEXP_EXTRACT(Extras, r'<PAGE_TITLE>(.*?)</PAGE_TITLE>'), ''), ' ', REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(DocumentIdentifier, r'^https?://[^/]+', ''), r'\.(html?|php|aspx?)$', ''), r'[-_/+]', ' '))) AS txt, LOWER(IFNULL(REGEXP_EXTRACT(Extras, r'<PAGE_TITLE>(.*?)</PAGE_TITLE>'), DocumentIdentifier)) AS title_key FROM `gdelt-bq.gdeltv2.gkg_partitioned` WHERE _PARTITIONTIME >= TIMESTAMP('2018-12-22') AND _PARTITIONTIME < TIMESTAMP('2024-01-01') AND STARTS_WITH(TranslationInfo, 'srclc:ind') ), totals AS ( SELECT day_utc, COUNT(*) AS n_ind_total FROM base GROUP BY day_utc ), pats AS ( SELECT * FROM UNNEST([ STRUCT('beras' AS commodity_group, r'\bberas\b|\bpadi\b|\bgabah\b' AS pat), ('bawang_putih', r'\bbawang putih\b'), ('bawang_merah', r'\bbawang merah\b'), ('cabai', r'\bcabai\b|\bcabe\b'), ('gula_pasir', r'\bgula pasir\b|\bgula kristal\b|\bgula\b'), ('minyak_goreng', r'\bminyak goreng\b|\bmigor\b|\bminyakita\b|\bcpo\b'), ('daging_sapi', r'\bdaging sapi\b|\bsapi impor\b|\bsapi bakalan\b'), ('daging_ayam', r'\bdaging ayam\b|\bayam ras\b|\bayam broiler\b|\blive bird\b'), ('telur_ayam', r'\btelur ayam\b|\bharga telur\b|\btelur\b'), ('umum', r'\bsembako\b|\bbahan pokok\b|\bbapok\b|\bpangan\b|\bbulog\b|\bbapanas\b') ]) ), hits AS ( SELECT b.day_utc, p.commodity_group, b.src, b.title_key, REGEXP_CONTAINS(b.txt, r'gagal panen|banjir|kekeringan|kemarau|el nino|hama|wabah|flu burung|\bpmk\b|longsor|gempa|cuaca|kelangkaan|langka|penimbunan|timbun') AS k_disrupt, REGEXP_CONTAINS(b.txt, r'impor|ekspor|larangan|kuota|\bhet\b|\bhap\b|harga eceran tertinggi|\bdmo\b|\bdpo\b|subsidi|neraca|regulasi|permendag|perbadan') AS k_policy, REGEXP_CONTAINS(b.txt, r'operasi pasar|\bsphp\b|pasar murah|pangan murah|stabilisasi|cadangan|bulog|bapanas|intervensi') AS k_stabil, REGEXP_CONTAINS(b.txt, r'pasokan|stok|panen|produksi|distribusi|gudang|petani|peternak|pakan|kapal|pelabuhan|angkut|pengiriman') AS k_supply, REGEXP_CONTAINS(b.txt, r'harga') AS k_price FROM base b JOIN pats p ON REGEXP_CONTAINS(b.txt, p.pat) AND NOT REGEXP_CONTAINS(b.txt, r'pondok cabe') ) SELECT h.day_utc, h.commodity_group, COUNT(*) AS n_raw, COUNT(DISTINCT h.title_key) AS n_all, COUNT(DISTINCT IF(k_disrupt, h.title_key, NULL)) AS n_disrupt, COUNT(DISTINCT IF(k_policy, h.title_key, NULL)) AS n_policy, COUNT(DISTINCT IF(k_stabil, h.title_key, NULL)) AS n_stabil, COUNT(DISTINCT IF(k_supply, h.title_key, NULL)) AS n_supply, COUNT(DISTINCT IF(k_price AND NOT (k_disrupt OR k_policy OR k_stabil OR k_supply), h.title_key, NULL)) AS n_price_only, COUNT(DISTINCT h.src) AS n_sources, ANY_VALUE(t.n_ind_total) AS n_ind_total FROM hits h JOIN totals t USING (day_utc) GROUP BY h.day_utc, h.commodity_group ORDER BY h.day_utc, h.commodity_group
